#include <cstddef>
#include <iostream>
#include <utility>

class Buffer {
public:
    explicit Buffer(std::size_t n) : datos_(new int[n]), n_(n) {
        std::cout << "constructor " << n_ << '\n';
    }
    ~Buffer() { delete[] datos_; }

    Buffer(const Buffer&) = delete;
    Buffer& operator=(const Buffer&) = delete;

    Buffer(Buffer&& otro) noexcept : datos_(otro.datos_), n_(otro.n_) {
        otro.datos_ = nullptr;
        otro.n_ = 0;
        std::cout << "move " << n_ << '\n';
    }

    Buffer& operator=(Buffer&& otro) noexcept {
        if (this != &otro) {
            delete[] datos_;
            datos_ = otro.datos_;
            n_ = otro.n_;
            otro.datos_ = nullptr;
            otro.n_ = 0;
        }
        return *this;
    }

    std::size_t tamano() const { return n_; }

private:
    int* datos_;
    std::size_t n_;
};

Buffer crear(std::size_t n) {
    return Buffer(n);   // elision garantizada: no hay move
}

int main() {
    Buffer a(4);
    Buffer b(std::move(a));
    std::cout << a.tamano() << ' ' << b.tamano() << '\n'; // 0 4

    Buffer c = crear(3);
    std::cout << c.tamano() << '\n';                      // 3
    return 0;
}

#include <iostream>
#include <optional>

std::optional<double> dividir(double a, double b) {
    if (b == 0.0) {
        return std::nullopt;
    }
    return a / b;
}

int main() {
    if (auto r = dividir(10.0, 4.0)) {
        std::cout << *r << '\n';        // 2.5
    }

    if (!dividir(1.0, 0.0)) {
        std::cout << "sin resultado\n";
    }

    auto r = dividir(9.0, 3.0);
    std::cout << r.value_or(-1.0) << '\n'; // 3
    return 0;
}

#include <iostream>
#include <string>
#include <variant>

using Valor = std::variant<int, double, std::string>;

void imprimir(const Valor& v) {
    std::visit([](const auto& x) {
        std::cout << x << '\n';
    }, v);
}

int main() {
    Valor a = 42;
    Valor b = 3.5;
    Valor c = std::string("modelo");

    imprimir(a);
    imprimir(b);
    imprimir(c);

    std::cout << std::get<double>(b) << '\n'; // 3.5

    if (const auto* p = std::get_if<int>(&a)) {
        std::cout << *p + 1 << '\n';          // 43
    }
    return 0;
}

