#include <iomanip>
#include <iostream>
#include <sstream>
#include <string>
#include <variant>

using Config = std::variant<int, double, std::string>;

struct Describir {
    std::string operator()(int v) const {
        return "entero: " + std::to_string(v);
    }
    std::string operator()(double v) const {
        std::ostringstream os;
        os << std::fixed << std::setprecision(1) << v;
        return "real: " + os.str();
    }
    std::string operator()(const std::string& v) const {
        return "texto: " + v;
    }
};

std::string describir(const Config& c) {
    return std::visit(Describir{}, c);
}

int main() {
    Config a = 7;
    Config b = 2.5;
    Config c = std::string("mse");

    std::cout << describir(a) << '\n'; // entero: 7
    std::cout << describir(b) << '\n'; // real: 2.5
    std::cout << describir(c) << '\n'; // texto: mse
    return 0;
}

